-- =============================================================================
-- Gestitel — Base de datos de referencia para revisión del cliente
-- Generado el 2026-10-21 desde las migraciones vigentes (core/0048 + customer/0006)
--
-- Contenido:
--   * Esquema "public": tablas de la plataforma (empresas, dominios, licencias,
--     bitácora de plataforma, configuración del Asistente IA) y tablas de Django.
--   * Esquema "demo": una empresa de ejemplo ("Empresa Demo") con la norma
--     integrada ISO/IEC 27001:2022 + ISO/IEC 27701:2025 y TODOS los datos de
--     semilla con que nace una empresa real (controles del Anexo A, cláusulas de
--     la Matriz de Brecha, catálogos, matrices de evaluación, rangos de
--     tasación, metas del Dashboard, periodo de riesgos, etc.).
--   * SIN datos de negocio de ningún cliente, SIN usuarios, SIN contraseñas,
--     SIN claves de API y SIN sesiones.
--
-- Requisitos: PostgreSQL 13 o superior.
-- Uso (ver README.md de esta carpeta):
--   createdb -U postgres -E UTF8 gestitel_revision
--   psql -U postgres -d gestitel_revision -f gestitel_base_de_datos.sql
-- =============================================================================

\set ON_ERROR_STOP on

